@startuml

class RepairShop {
  + name : string
  + address : string
}

class Repair {
  + duration : string
  + cost : float
}

class Vehicle {
  + licensePlateNumber : string
  + mileage : int
}

class Order {
  + packageSize : string
  + comment : string
  + startTime : datetime
  + finishTime : datetime
  + pickUpAddress : string
  + deliveryAddress : string
}

abstract class Employee {
  + name : string
  + socialSecurityNumber : string
  + username : string
  + password : string
}

class Driver extends Employee {}

abstract class OtherEmployee extends Employee {}

class Planner extends OtherEmployee {}

class AdministrationEmployee extends OtherEmployee {
  + fieldOfActivity : string
}

class PartnerFirm {
  + name : string
  + address : string
}

class Customer {
  + name : string
  + billingAddress : string
}

RepairShop "1" -- "*" Repair
Repair "*" -- "1" Vehicle
Repair "*" -- "1" Employee
Vehicle "1" -- "*" Order
Driver "1" -- "*" Order
Planner "1" -- "*" Order : assigns
AdministrationEmployee "0..1" -- "*" Order : places
Order "*" -- "0..1" PartnerFirm
Order "*" -- "1" Customer
Order "*" -- "1" Vehicle
Order "*" -- "1" Driver : completes

@enduml

